function uncertainPreview(app,report='report-a') {app._uiRecoveryOwner=report;app._uiLastMutationRun='preview-a';app._uiLastMutationPrivate=true;app.uncertainRun=true;}
test('switching reports resets recovery but same-report reload preserves uncertainty',async()=>{const root=installDOM(),f=fixture(),app=new ReportApp(root,f.adapter);await app.start();await app.openDraft('report-a');uncertainPreview(app);await app.openDraft('report-a');assert.equal(app._uiRecoveryOwner,'report-a');assert.equal(app._uiLastMutationRun,'preview-a');assert.equal(app.uncertainRun,true);await assert.rejects(app.previewDraft(),/forbidden/);await app.openDraft('report-b');assert.equal(app._uiRecoveryOwner,'report-b');assert.equal(app._uiLastMutationRun,null);assert.equal(app._uiLastMutationPrivate,false);assert.equal(app.uncertainRun,false);app.mode='builder';app.render();assert(!root.querySelectorAll('button').some(b=>b.textContent==='Inspect last retained run'));assert.equal(root.querySelectorAll('button').find(b=>b.textContent==='Private preview').disabled,false);app.close();});

