test('late failed preview cannot attach old-report recovery to a newer report',async()=>{const root=installDOM(),f=fixture();let rejectPreview;const base=f.adapter.call.bind(f.adapter);f.adapter.call=(name,args)=>name==='reporting_authoring_preview_v1'?new Promise((resolve,reject)=>{rejectPreview=reject;}):base(name,args);const app=new ReportApp(root,f.adapter);await app.start();await app.openDraft('report-a');const preview=app.previewDraft();const rejected=assert.rejects(preview,/unavailable/);assert.equal(app.uncertainRun,true);await app.openDraft('report-b');rejectPreview(appError('unavailable',true));await rejected;assert.equal(app._uiRecoveryOwner,'report-b');assert.equal(app._uiLastMutationRun,null);assert.equal(app.uncertainRun,false);app.close();});

function retainedStatus(run,state='completed',report='report-a',isPrivate=true,code='') {return {version:'reporting-view-v1',timezone:'UTC',locale:'en-US',page_bounds:{offset:0,limit:100,total:0},summary:{kind:'report',run,target:{kind:'report',id:report,revision:1},private:isPrivate,state,code,expires_at:'2099-01-01T00:00:00Z'},selection:{kind:'report',run},pages:[]};}
test('terminal read after denied private preview enables future preview while pending and foreign reads cannot clear',async()=>{
 const root=installDOM(),f=fixture(),base=f.adapter.call.bind(f.adapter);let denied=true,status='completed',target='report-a';
 f.adapter.call=async(name,args)=>{
  if(name==='reporting_authoring_preview_v1')return {structuredContent:{result:{id:'preview-a',private:true}}};
  if(name==='reporting_authoring_execute_v1')return {structuredContent:{result:{id:'preview-a',private:true,state:'completed'}}};
  if(name==='reporting_view')return denied?{isError:true,structuredContent:{error:{code:'not_found'}}}:{structuredContent:{result:retainedStatus(args.run,status,target)}};
  return base(name,args);
 };
 const app=new ReportApp(root,f.adapter);await app.start();await app.openDraft('report-a');app.mode='builder';
 await assert.rejects(app.previewDraft(),e=>e.needsRunAuthority===true);assert.equal(app.uncertainRun,true);assert.equal(app._uiLastMutationRun,'preview-a');
 denied=false;status='running';await app.openRun('preview-a',true);assert.equal(app.uncertainRun,true);
 status='unknown';await app.openRun('preview-a',true);assert.equal(app.uncertainRun,true);
 status='completed';await app.openRun('foreign-run',true);assert.equal(app.uncertainRun,true);
 target='report-b';await assert.rejects(app.openRun('preview-a',true),/stale_validation/);assert.equal(app.uncertainRun,true);assert.equal(app.preview,null);
 target='report-a';await app.openRun('preview-a',true);assert.equal(app.uncertainRun,false);app.closePreview();app.render();
 assert.equal(root.querySelectorAll('button').find(b=>b.textContent==='Private preview').disabled,false);
 await app.openDraft('report-a');assert.equal(app.uncertainRun,false);app.close();
});

