test('nested retained viewer size requests use the entire report root and one outer size owner',()=>{const root=installDOM(),sizes=[],app=new ReportApp(root,{resize:(width,height)=>sizes.push({width,height})}),bridge=app.retainedBridge();bridge.resize(200,120);assert.deepEqual(sizes,[{width:1000,height:800}]);app.requestRootSize();bridge.resize(500,300);assert.equal(sizes.length,1,'nested and root observers do not compete with duplicate heights');root.getBoundingClientRect=()=>({width:1200,height:1400});bridge.resize(300,150);assert.deepEqual(sizes.at(-1),{width:1200,height:1400});app.close();bridge.resize(100,100);assert.equal(sizes.length,2,'closed app does not resize');});

