async function mappingApp(formatting=false,chartTitle='Revenue'){
 const source=(id='source',revision=7)=>{const view=(formatting?formatView:mapView)(id,revision);view.block.outputs[0].mapping.options.title=chartTitle;return view;};
 const root=installDOM(),f=fixture(),base=f.adapter.call.bind(f.adapter);let privateView=null,fail='',delayed=null;
 f.adapter.call=async(name,args)=>{let result;
  if(name==='chart_catalog')result=mapClone(mapCatalog);
  else if(name==='reporting_authoring_block_read_v1'){if(fail.startsWith('read:'))throw appError(fail.slice(5));result=privateView&&args.block===privateView.block.state.id?mapClone(privateView):source(args.block,args.revision);}
  else if(name==='reporting_authoring_block_copy_v1'||name==='reporting_authoring_block_mapping_v1'){if(fail==='save')throw appError('unavailable',true);privateView=formatting?formatSaved(privateView||source(),args):mapSaved(args,name.includes('block_copy'));result=mapClone(privateView);}
  else if(name==='reporting_authoring_block_validate_v1'){if(fail==='validate')throw appError('unavailable',true);if(delayed)return new Promise(resolve=>{delayed.resolve=()=>resolve({structuredContent:{result:mapValidation(privateView)}});});result=mapValidation(privateView);privateView.block.state=mapClone(result.state);privateView.block.validation=mapClone(result.evidence);}
  else return base(name,args);
  f.calls.push({name,args});return {structuredContent:{result}};
 };
 const app=new ReportApp(root,f.adapter);await app.start();app.mode='builder';await app.openDraft('report-a');app.enablePages();app.blockDescription={resource:{target:{id:'source',revision:7}}};app.addOutput({id:'amount',kind:'chart',title:'Revenue'});app.selectWidget(app.selectedWidget);await app.save();app.render();return {app,root,...f,widget:()=>app.activePage().widgets.find(w=>w.block),fail:kind=>{fail=kind;},delay:()=>{delayed={};return delayed;}};
}
