test('unsupported allocation keeps creation unavailable across report, copy and dataset forms without ID fallbacks',async()=>{const root=installDOM(),f=fixture();f.adapter.supportsTargetAllocation=()=>false;const app=new ReportApp(root,f.adapter);await app.start();await app.changeMode('builder');app.beginNewReport();app.render();assert(root.textContent.includes('Creation is unavailable in this host'));assert.equal(root.querySelectorAll('button').find(b=>b.textContent==='Create report').disabled,true);await assert.rejects(app.createDraft(),e=>e.allocationUnavailable===true);assert.equal(f.allocations.length,0);await app.openDraft('report-a');assert(app.session.definition);app.close();for(const kind of ['copy','dataset']){const current=kind==='copy'?await mappingApp():await datasetAppFixture(),a=current.app,adapter=current.adapter||current.f.adapter;adapter.supportsTargetAllocation=()=>false;if(kind==='copy'){await a.openMapping(current.widget());a.mapping.edit(d=>d.kind='column');}else await stageDataset(a);a.render();assert(current.root.textContent.includes('Creation is unavailable in this host'));assert(!current.root.querySelectorAll('input').some(e=>/\bID\b/.test(e.getAttribute('aria-label')||'')));const action=kind==='copy'?'Save chart':'Prepare chart';assert.equal(current.root.querySelectorAll('button').find(b=>b.textContent===action).disabled,true);const calls=kind==='copy'?current.calls:current.native.calls,before=calls.length;await assert.rejects(kind==='copy'?a.saveMapping():a.prepareDataset(),e=>e.allocationUnavailable===true);assert.equal(calls.length,before);a.close();}});

