test('first report creation uses a separate host intent entry without inventing native builder authority',async()=>{for(const available of [true,false]){const root=installDOM(),f=fixture(),base=f.adapter.call.bind(f.adapter);f.adapter.supportsTargetAllocation=()=>available;f.adapter.call=async(name,args)=>name==='reporting_authoring_capabilities_v1'&&!args.report?{structuredContent:{result:{...caps(''),builder:false,consumer:false}}}:base(name,args);const app=new ReportApp(root,f.adapter);await app.start();assert.equal(app.capabilities.builder,false);assert.equal(root.querySelectorAll('button').find(b=>b.textContent==='Build').disabled,true);const create=root.querySelectorAll('button').find(b=>b.textContent==='New report');assert.equal(!!create,available);if(available){create.emit('click');for(let i=0;i<4;i++)await Promise.resolve();app.render();assert.equal(app.mode,'consumer');assert(root.querySelectorAll('input').some(e=>e.getAttribute('aria-label')==='Report title'));assert(!f.calls.some(c=>c.name==='reporting_authoring_drafts_v1'));app.newTitle='My first report';await app.createDraft();assert.equal(app.mode,'builder');assert.equal(app.capabilities.can_create,true);assert.equal(app.session.definition.metadata[0].title,'My first report');assert.equal(f.allocations.length,1);assert(f.calls.some(c=>c.name==='reporting_authoring_capabilities_v1'&&c.args.report==='allowed-new'));assert(!f.calls.some(c=>c.name==='reporting_authoring_drafts_v1'));}app.close();}});

const retainedHostTools=['reporting_authoring_capabilities_v1','reporting_search','reporting_describe','reporting_runs','reporting_view'];
const textHostTools=[...retainedHostTools,...['drafts','read','create','save'].map(action=>`reporting_authoring_${action}_v1`)];
async function registeredApp(kind,names,{first=false,allocation=true,denyCreate=false}={}) {
 const {MCPReportAdapter,EmbeddedReportAdapter}=await import('./bridge.js'),root=installDOM(),f=fixture(),call=f.adapter.call.bind(f.adapter),listeners=new Map(),messages=[];
 const embedded=kind==='embedded',envelope=message=>embedded?{protocol:'chartworks-report-app-v1',frame:'profile-frame',generation:1,...message}:{jsonrpc:'2.0',...message};
 const parent={postMessage(message){messages.push(message);if(message.id===undefined)return;queueMicrotask(async()=>{
  let result;
  if(message.method=== (embedded?'initialize':'ui/initialize')){
   const tools={version:'chartworks-host-tools-v1',names:[...names]},allocate={version:'report-app-allocation-v1'};
   result=embedded?{challenge:'profile-challenge-1',tools:true,capabilities:{supported_tools:tools,...(allocation?{target_allocation:allocate}:{})}}:{protocolVersion:'2026-01-26',hostCapabilities:{serverTools:{}},hostContext:{'chartworks/supported-tools':tools,...(allocation?{'chartworks/target-allocation':allocate}:{})}};
  }else if(message.method==='app/allocate-target')result=await f.adapter.allocateTarget(message.params);
  else if(message.method==='tools/call'){
   const {name,arguments:args}=message.params;assert(names.includes(name),`Unexpected host tool ${name}`);
   if(name==='reporting_authoring_capabilities_v1'&&(first&&!args.report||denyCreate&&args.report==='allowed-new')){f.calls.push({name,args});result={structuredContent:{result:{...caps(args.report),...(first&&!args.report?{builder:false,consumer:false}:{can_create:false})}}};}
   else if(name==='reporting_describe'){f.calls.push({name,args});result={structuredContent:{result:{resource:{target:args.target,title:'Published text'},filters:[{page:'main',label:'Period',parameter:{name:'period',type:'integer'}}],timezone:'UTC'}}};}
   else if(name==='reporting_runs'){f.calls.push({name,args});result={structuredContent:{result:{items:[{run:'retained-a',state:'completed',created_at:'2026-01-01'}],next:''}}};}
   else if(name==='reporting_view'){f.calls.push({name,args});result={structuredContent:{result:retainedStatus(args.run,'completed','report-a',false)}};}
   else result=await call(name,args);
  }else throw new Error('Unexpected request '+message.method);
  listeners.get('message')?.({source:parent,origin:'https://host.example',data:envelope({id:message.id,result})});
 });}};
 const win={parent,addEventListener:(name,fn)=>listeners.set(name,fn),removeEventListener:name=>listeners.delete(name)},bridge=embedded?new EmbeddedReportAdapter({win,origin:'https://host.example',frame:'profile-frame',generation:1,challenge:'profile-challenge-1'}):new MCPReportAdapter(win),app=new ReportApp(root,bridge);
 await app.start();return {root,f,app,bridge,messages,close(){app.close();bridge.close();}};
}
const buttonLabels=root=>root.querySelectorAll('button').map(b=>b.textContent);
const advancedLabels=['Add published output','Create from dataset','Choose business filter','Save selected content','Private preview','Validate data','Edit chart','Prepare chart','Publish report','Run with these filters'];

